(function(root){
const C=ToolHubNextCore;
root.ToolHubNextUI={create(id,H){
const {make,panel,field,check,ta,outputButtons,outputActions,ready,status,q}=H;
function workerRun(p,kind,args,done){p.cancel?.();const worker=new Worker('next-worker.js?v=20261019-next');const button=q(p,'.n-run');button.disabled=true;status(p,'Đang xử lý trên thiết bị…');let timer;const cancel=()=>{worker.terminate();clearTimeout(timer);button.disabled=false;p.cancel=null;return true};p.cancel=cancel;timer=setTimeout(()=>{cancel();status(p,'Đã dừng sau 3 giây. Hãy giảm nội dung hoặc kiểm tra lại lịch.',true)},3000);worker.onerror=()=>{cancel();status(p,'Không khởi động được bộ xử lý. Hãy tải lại trang.',true)};worker.onmessage=e=>{cancel();if(e.data.ok)done(e.data.result);else status(p,e.data.error,true)};worker.postMessage({kind,args})}
if(id==='yaml'){
 const p=make(id,'<div class="a-toolbar"><label for="nt-yaml-mode">Chiều chuyển đổi</label><select id="nt-yaml-mode"><option value="json-yaml">JSON → YAML</option><option value="yaml-json">YAML → JSON</option></select></div><div class="a-columns">'+panel('Dữ liệu đầu vào',ta('nt-yaml-input','JSON hoặc YAML')+'<label class="a-file-button">Mở file JSON / YAML<input id="nt-yaml-file" type="file" accept=".json,.yaml,.yml,.txt"></label><p class="a-hint">Tối đa 200.000 ký tự. YAML dùng kiểu dữ liệu tương thích JSON; chú thích không được giữ trong kết quả. Không hỗ trợ nhiều tài liệu YAML trong một file.</p>')+panel('Kết quả',ta('nt-yaml-output','Nội dung đã chuyển đổi')+outputButtons+'<button class="a-reuse" disabled>Đổi chiều và dùng kết quả ⇄</button>')+'</div><div class="a-toolbar"><button class="a-primary n-run">Chuyển đổi</button><button class="n-example">Dùng ví dụ</button><button class="n-clear">Xóa</button></div>');let result='',ext='yaml';const input=q(p,'#nt-yaml-input'),output=q(p,'#nt-yaml-output'),mode=q(p,'#nt-yaml-mode');output.readOnly=true;const invalidate=()=>{p.cancel?.();result='';output.value='';ready(p,false);status(p,'')};const run=()=>{invalidate();workerRun(p,'yaml',[input.value,mode.value],r=>{result=r;ext=mode.value==='json-yaml'?'yaml':'json';output.value=r;ready(p,true);status(p,'Đã chuyển đổi. Có thể sao chép hoặc tải file.')})};q(p,'.n-run').onclick=run;q(p,'.n-example').onclick=()=>{input.value=mode.value==='json-yaml'?'{"name":"ToolHub","enabled":true,"tools":["JSON","YAML"],"version":1}':'name: ToolHub\nenabled: true\ntools:\n  - JSON\n  - YAML\nversion: 1\n';run()};q(p,'.n-clear').onclick=()=>{input.value='';q(p,'#nt-yaml-file').value='';invalidate()};q(p,'.a-reuse').onclick=()=>{input.value=result;mode.value=ext==='yaml'?'yaml-json':'json-yaml';invalidate()};input.oninput=invalidate;mode.onchange=invalidate;let revision=0;q(p,'#nt-yaml-file').onchange=async e=>{const rev=++revision,file=e.target.files[0];if(!file)return;invalidate();if(file.size>800000)return status(p,'File quá lớn. Chọn file tối đa 800 KB và 200.000 ký tự.',true);try{const value=await file.text();if(rev!==revision)return;input.value=value.replace(/^\uFEFF/,'');mode.value=/\.ya?ml$/i.test(file.name)?'yaml-json':'json-yaml';status(p,'Đã đọc file. Nhấn Chuyển đổi.')}catch{status(p,'Không đọc được file UTF-8.',true)}};outputActions(p,()=>result,()=>`toolhub-config.${ext}`);return p;
}
if(id==='cron'){
 const p=make(id,'<div class="a-columns">'+panel('Tạo lịch cron','<label for="nt-cron-preset">Mẫu lịch</label><select id="nt-cron-preset"><option value="*/5 * * * *">Mỗi 5 phút</option><option value="0 * * * *">Mỗi giờ</option><option value="0 9 * * *">Hằng ngày lúc 09:00</option><option value="0 9 * * 1-5">09:00 các ngày T2–T6</option><option value="0 0 1 * *">Ngày đầu mỗi tháng</option><option value="custom">Tự nhập</option></select>'+field('nt-cron-expression','Biểu thức cron (5 trường)','*/5 * * * *')+'<div class="n-cron-builder">'+['Phút','Giờ','Ngày','Tháng','Thứ'].map((label,i)=>'<div>'+field('nt-cron-'+i,label,['*/5','*','*','*','*'][i])+'</div>').join('')+'</div><label for="nt-cron-zone">Múi giờ</label><select id="nt-cron-zone"><option value="Asia/Ho_Chi_Minh">Việt Nam · Asia/Ho_Chi_Minh</option><option value="UTC">UTC</option><option value="Asia/Tokyo">Tokyo</option><option value="Asia/Singapore">Singapore</option><option value="Europe/London">London</option><option value="America/New_York">New York</option></select>'+field('nt-cron-start','Tính từ thời điểm ISO (để trống = hiện tại)','','text')+'<p class="a-hint">Ví dụ: 2026-10-19T08:00:00+07:00. Lịch hỗ trợ *, số, danh sách 1,3,5, khoảng 1-5 và bước */5. Chỉ xem lịch; công cụ không tự chạy công việc.</p><div class="a-toolbar"><button class="a-primary n-run">Xem lịch chạy</button><button class="n-now">Dùng thời điểm hiện tại</button></div>')+panel('10 lần chạy tiếp theo','<p class="n-cron-description a-summary">Chọn mẫu hoặc nhập cron rồi xem lịch.</p><div class="n-cron-fields"></div><ol class="n-cron-times"></ol>'+ta('nt-cron-output','Lịch chạy dạng văn bản')+outputButtons)+'</div>');let result='';const expression=q(p,'#nt-cron-expression'),preset=q(p,'#nt-cron-preset');q(p,'#nt-cron-output').readOnly=true;const invalidate=()=>{p.cancel?.();result='';ready(p,false);q(p,'#nt-cron-output').value='';q(p,'.n-cron-times').replaceChildren();q(p,'.n-cron-fields').replaceChildren();q(p,'.n-cron-description').textContent='Lịch đã thay đổi. Nhấn Xem lịch chạy.';status(p,'')};const sync=()=>{const parts=expression.value.trim().split(/\s+/);for(let i=0;i<5;i++)q(p,'#nt-cron-'+i).value=parts[i]||''};const run=()=>{invalidate();workerRun(p,'cron',[expression.value,q(p,'#nt-cron-zone').value,q(p,'#nt-cron-start').value.trim()||new Date().toISOString()],r=>{const formatter=new Intl.DateTimeFormat('vi-VN',{timeZone:r.timezone,dateStyle:'full',timeStyle:'long'});q(p,'.n-cron-description').textContent=r.description+' Múi giờ: '+r.timezone;for(const f of r.fields){const row=document.createElement('p');row.textContent=f.name+': '+f.value+' · '+f.explanation;q(p,'.n-cron-fields').append(row)}for(const time of r.times){const li=document.createElement('li');li.textContent=formatter.format(new Date(time));q(p,'.n-cron-times').append(li)}result=r.expression+'\n'+r.timezone+'\n'+r.description+'\n'+r.times.map(t=>formatter.format(new Date(t))+' | '+t).join('\n');q(p,'#nt-cron-output').value=result;ready(p,true);status(p,'Đã tính '+r.times.length+' lần chạy tiếp theo.')})};expression.oninput=()=>{preset.value='custom';sync();invalidate()};for(let i=0;i<5;i++)q(p,'#nt-cron-'+i).oninput=()=>{expression.value=Array.from({length:5},(_,j)=>q(p,'#nt-cron-'+j).value.trim()).join(' ');preset.value='custom';invalidate()};preset.onchange=()=>{if(preset.value!=='custom'){expression.value=preset.value;sync()}invalidate()};q(p,'#nt-cron-zone').onchange=invalidate;q(p,'#nt-cron-start').oninput=invalidate;q(p,'.n-run').onclick=run;q(p,'.n-now').onclick=()=>{q(p,'#nt-cron-start').value='';run()};outputActions(p,()=>result,'toolhub-cron.txt');return p;
}
if(id==='markdown'){
 const p=make(id,'<div class="a-toolbar"><button class="n-example">Dùng ví dụ</button><button class="n-clear">Xóa</button><button class="n-md-download">Tải .md</button></div><div class="a-columns">'+panel('Soạn Markdown',ta('nt-markdown-input','Nội dung Markdown')+'<p class="a-hint">Hỗ trợ tiêu đề, bảng, danh sách, liên kết và khối code. Hình ảnh và nội dung nhúng bị tắt để không gửi yêu cầu đến website bên ngoài.</p>')+panel('Xem trước trực tiếp','<div class="n-markdown-preview" aria-label="Bản xem trước Markdown"></div>')+'</div>'+panel('HTML để sử dụng',ta('nt-markdown-output','HTML đã làm sạch')+outputButtons));let html='',timer;const input=q(p,'#nt-markdown-input'),output=q(p,'#nt-markdown-output');output.readOnly=true;const run=()=>{clearTimeout(timer);try{html=DOMPurify.sanitize(C.markdownRaw(input.value),{ALLOWED_TAGS:['h1','h2','h3','h4','h5','h6','p','br','hr','strong','em','del','blockquote','ul','ol','li','pre','code','a','table','thead','tbody','tr','th','td','input'],ALLOWED_ATTR:['href','title','type','checked','disabled','start','align'],FORBID_ATTR:['style','id','name'],ALLOW_DATA_ATTR:false});const view=q(p,'.n-markdown-preview');view.innerHTML=html;view.querySelectorAll('input').forEach(el=>{el.type='checkbox';el.disabled=true});view.querySelectorAll('a').forEach(a=>{const href=a.getAttribute('href')||'';if(!/^(https?:|mailto:|#)/i.test(href))a.removeAttribute('href');a.target='_blank';a.rel='noopener noreferrer'});html=view.innerHTML;output.value=html;ready(p,!!html);q(p,'.n-md-download').disabled=!input.value;status(p,input.value?'Đã cập nhật bản xem trước.':'')}catch(e){html='';output.value='';q(p,'.n-markdown-preview').replaceChildren();ready(p,false);status(p,e.message,true)}};input.oninput=()=>{clearTimeout(timer);html='';output.value='';ready(p,false);q(p,'.n-md-download').disabled=!input.value;timer=setTimeout(run,180)};q(p,'.n-example').onclick=()=>{input.value='# ToolHub\n\nCông cụ cho **công việc mỗi ngày**.\n\n## Việc cần làm\n- [x] Soạn Markdown\n- [ ] Xuất HTML\n\n| Công cụ | Trạng thái |\n| --- | --- |\n| Markdown | Sẵn sàng |\n\n```js\nconsole.log("Xin chào!");\n```\n\n[Website mẫu](https://example.com)';run()};q(p,'.n-clear').onclick=()=>{input.value='';run()};q(p,'.n-md-download').onclick=()=>H.download(new Blob([input.value],{type:'text/markdown;charset=utf-8'}),'toolhub-note.md');outputActions(p,()=>html,'toolhub-note.html','text/html;charset=utf-8');run();return p;
}
if(id==='contrast'){
 const p=make(id,'<div class="a-columns">'+panel('Chọn màu','<div class="a-small-grid"><div>'+field('nt-contrast-fg','Màu chữ HEX','#236B52')+field('nt-contrast-fg-picker','Chọn màu chữ','#236b52','color')+'</div><div>'+field('nt-contrast-bg','Màu nền HEX','#FFFFFF')+field('nt-contrast-bg-picker','Chọn màu nền','#ffffff','color')+'</div></div><div class="a-toolbar"><button class="n-swap">Đảo màu chữ / nền</button><button class="n-example">Mẫu đen / trắng</button></div><p class="a-hint">Chỉ áp dụng cho hai màu đặc, không trong suốt. Chữ lớn: từ 24 px, hoặc chữ đậm từ khoảng 18,67 px.</p><a href="https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html" target="_blank" rel="noopener noreferrer">Tham khảo tiêu chí tương phản WCAG 2.2 ↗</a>')+panel('Kết quả & xem trước','<strong class="n-contrast-ratio"></strong><ul class="n-contrast-checks"></ul><div class="n-contrast-preview"><strong>Tiêu đề mẫu · 24 px</strong><p>Văn bản mẫu · 16 px. Kiểm tra độ rõ của chữ trên màu nền đã chọn.</p></div>'+ta('nt-contrast-output','Báo cáo tương phản')+outputButtons)+'</div>');let report='';q(p,'#nt-contrast-output').readOnly=true;const run=()=>{try{const r=C.contrast(q(p,'#nt-contrast-fg').value,q(p,'#nt-contrast-bg').value);report=`${r.foreground} trên ${r.background}\nTỷ lệ: ${r.ratio.toFixed(2)}:1`;q(p,'.n-contrast-ratio').textContent=r.ratio.toFixed(2)+':1';const list=q(p,'.n-contrast-checks');list.replaceChildren();for(const [key,label,limit] of [['aa','AA · chữ thường',4.5],['aaLarge','AA · chữ lớn',3],['aaa','AAA · chữ thường',7],['aaaLarge','AAA · chữ lớn',4.5]]){const li=document.createElement('li');li.textContent=`${r[key]?'✓ Đạt':'✕ Chưa đạt'} ${label} (≥ ${limit}:1)`;li.className=r[key]?'n-pass':'n-fail';list.append(li);report+='\n'+li.textContent}const view=q(p,'.n-contrast-preview');view.style.color=r.foreground;view.style.backgroundColor=r.background;for(const k of ['fg','bg'])q(p,'#nt-contrast-'+k+'-picker').value=k==='fg'?r.foreground:r.background;q(p,'#nt-contrast-output').value=report;ready(p,true);status(p,'Đánh giá theo tỷ lệ chính xác, trước khi làm tròn số hiển thị.')}catch(e){report='';q(p,'#nt-contrast-output').value='';q(p,'.n-contrast-ratio').textContent='—';q(p,'.n-contrast-checks').replaceChildren();ready(p,false);status(p,e.message,true)}};for(const k of ['fg','bg']){q(p,'#nt-contrast-'+k).oninput=run;q(p,'#nt-contrast-'+k+'-picker').oninput=e=>{q(p,'#nt-contrast-'+k).value=e.target.value;run()}}q(p,'.n-swap').onclick=()=>{const a=q(p,'#nt-contrast-fg'),b=q(p,'#nt-contrast-bg'),v=a.value;a.value=b.value;b.value=v;run()};q(p,'.n-example').onclick=()=>{q(p,'#nt-contrast-fg').value='#000000';q(p,'#nt-contrast-bg').value='#ffffff';run()};outputActions(p,()=>report,'toolhub-contrast.txt');run();return p;
}
if(id==='cssgen'){
 const number=(key,label,value,min,max)=>'<div>'+field('nt-css-'+key,label,value,'number')+'</div>';
 const p=make(id,'<div class="a-columns">'+panel('Thiết lập CSS','<label for="nt-css-type">Loại CSS</label><select id="nt-css-type"><option value="gradient">Gradient</option><option value="shadow">Box shadow</option><option value="radius">Border radius</option></select><div class="a-small-grid"><div>'+field('nt-css-color','Màu chính','#236b52','color')+'</div><div class="n-css-second">'+field('nt-css-second','Màu thứ hai','#d6ead9','color')+'</div></div><div class="n-css-gradient a-small-grid">'+number('angle','Góc (0–360°)',135)+number('stop1','Điểm màu đầu (%)',0)+number('stop2','Điểm màu cuối (%)',100)+'</div><div class="n-css-shadow" hidden><div class="a-small-grid">'+number('x','Lệch ngang (px)',0)+number('y','Lệch dọc (px)',12)+number('blur','Độ nhòe (px)',24)+number('spread','Độ lan (px)',0)+number('opacity','Độ đậm (%)',25)+'</div>'+check('nt-css-inset','Bóng bên trong (inset)')+'</div><div class="n-css-radius a-small-grid" hidden>'+number('tl','Góc trên trái (px)',24)+number('tr','Góc trên phải (px)',24)+number('br','Góc dưới phải (px)',24)+number('bl','Góc dưới trái (px)',24)+'</div><button class="n-reset">Khôi phục mặc định</button>')+panel('Xem trước trực tiếp','<div class="n-css-stage"><div class="n-css-box" aria-label="Khối xem trước CSS"></div></div>'+ta('nt-css-output','CSS được tạo')+outputButtons)+'</div>');let result='';const defaults={angle:135,stop1:0,stop2:100,x:0,y:12,blur:24,spread:0,opacity:25,tl:24,tr:24,br:24,bl:24};const limits={angle:[0,360],stop1:[0,100],stop2:[0,100],x:[-100,100],y:[-100,100],blur:[0,150],spread:[-100,100],opacity:[0,100],tl:[0,200],tr:[0,200],br:[0,200],bl:[0,200]};for(const [k,v] of Object.entries(limits)){q(p,'#nt-css-'+k).min=v[0];q(p,'#nt-css-'+k).max=v[1]}q(p,'#nt-css-output').readOnly=true;const run=()=>{const type=q(p,'#nt-css-type').value;for(const t of ['gradient','shadow','radius'])q(p,'.n-css-'+t).hidden=type!==t;q(p,'.n-css-second').hidden=type!=='gradient';try{const data={type,color:q(p,'#nt-css-color').value,second:q(p,'#nt-css-second').value,inset:q(p,'#nt-css-inset').checked};for(const k of Object.keys(defaults))data[k]=q(p,'#nt-css-'+k).value;result=C.cssGenerate(data);const box=q(p,'.n-css-box');box.removeAttribute('style');box.style.cssText='background: '+data.color+';'+result;q(p,'#nt-css-output').value=result;ready(p,true);status(p,'Đã cập nhật CSS và bản xem trước.')}catch(e){result='';q(p,'#nt-css-output').value='';ready(p,false);status(p,e.message,true)}};p.querySelectorAll('input,select').forEach(el=>el.oninput=run);q(p,'.n-reset').onclick=()=>{for(const[k,v]of Object.entries(defaults))q(p,'#nt-css-'+k).value=v;q(p,'#nt-css-color').value='#236b52';q(p,'#nt-css-second').value='#d6ead9';q(p,'#nt-css-inset').checked=false;run()};outputActions(p,()=>'.toolhub-element {\n  '+result+'\n}','toolhub-style.css','text/css');run();return p;
}
}};
})(globalThis);
